// A TLS socket costs about 40 kB of RAM, so the pool stays tiny: two sockets
// let a browser fetch the page and post the form without opening a second
// connection in parallel. If the heap cannot take it, start() retries with
// one.
#define WEB_SOCKETS 2

static httpd_handle_t server = NULL;
static bool busy = false;           // a start/stop worker is running
