//
// Basic auth.
//

static const char B64[] =
    "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

// Base64 of "user:password", written by hand so the whole check stays one
// comparison against the client header.
static void base64_encode(const char *in, char *out, size_t cap)
{
    size_t o = 0;
    size_t len = strlen(in);
    for (size_t i = 0; i < len && o + 4 < cap; i += 3) {
        uint32_t v = (uint8_t)in[i] << 16;
        if (i + 1 < len) v |= (uint8_t)in[i + 1] << 8;
        if (i + 2 < len) v |= (uint8_t)in[i + 2];
        out[o++] = B64[(v >> 18) & 0x3F];
        out[o++] = B64[(v >> 12) & 0x3F];
        out[o++] = (i + 1 < len) ? B64[(v >> 6) & 0x3F] : '=';
        out[o++] = (i + 2 < len) ? B64[v & 0x3F] : '=';
    }
    out[o] = '\0';
}

static void build_expected_auth(void)
{
    expected_auth[0] = '\0';
    if (settings.web_password[0] == '\0') return; // no password, no login
    char raw[100];
    char encoded[140];
    snprintf(raw, sizeof(raw), "%s:%s", settings.web_user, settings.web_password);
    base64_encode(raw, encoded, sizeof(encoded));
    snprintf(expected_auth, sizeof(expected_auth), "Basic %s", encoded);
}

static bool auth_ok(httpd_req_t *req)
{
    if (expected_auth[0] == '\0') return true;
    char got[176];
    if (httpd_req_get_hdr_value_len(req, "Authorization") == 0) return false;
    if (httpd_req_get_hdr_value_str(req, "Authorization", got, sizeof(got)) != ESP_OK) {
        return false;
    }
    return strcmp(got, expected_auth) == 0;
}

static esp_err_t deny(httpd_req_t *req)
{
    httpd_resp_set_hdr(req, "WWW-Authenticate", "Basic realm=\"moonstation\"");
    return httpd_resp_send_err(req, HTTPD_401_UNAUTHORIZED, "login required");
}

//
// The settings table the page may read and write. Everything outside of it
// stays a compile time value, see the comment on settings_t.
//

typedef enum { F_STR, F_U8, F_U16, F_U32, F_I8, F_I16 } field_type_t;

typedef struct {
    const char *key;
    field_type_t type;
    size_t offset;
    size_t size; // string capacity, unused for numbers
    int32_t lo;  // clamp range for numbers
    int32_t hi;
} field_t;

#define FIELD(f, t, s, lo, hi) {#f, t, offsetof(settings_t, f), s, lo, hi}

static const field_t FIELDS[] = {
    FIELD(wifi_ssid, F_STR, 33, 0, 0),
    FIELD(wifi_password, F_STR, 65, 0, 0),
    FIELD(slide_dir, F_STR, 32, 0, 0),
    FIELD(slide_interval_ms, F_U32, 0, 1000, 3600000),
    FIELD(slide_fade_ms, F_U16, 0, 0, 2000),
    FIELD(backlight_full_pct, F_U8, 0, 10, 100),
    FIELD(backlight_dim_pct, F_U8, 0, 0, 100),
    FIELD(backlight_deep_pct, F_U8, 0, 0, 100),
    FIELD(backlight_dim_after_sec, F_U8, 0, 1, 255),
    FIELD(backlight_deep_after_sec, F_U8, 0, 1, 255),
    FIELD(clock_deep_sleep_from, F_U8, 0, 0, 23),
    FIELD(clock_deep_sleep_to, F_U8, 0, 0, 23),
    FIELD(clock_deep_sleep_enable, F_U8, 0, 0, 1),
    FIELD(ntp_daily_sync_hour, F_I8, 0, -1, 23),
    FIELD(ntp_server, F_STR, 64, 0, 0),
    FIELD(tz_std_offset_min, F_I16, 0, -720, 840),
    FIELD(tz_eu_dst, F_U8, 0, 0, 1),
    FIELD(audio_volume, F_U8, 0, 0, 100),
    FIELD(battery_warn_pct, F_U16, 0, 0, 100),
    FIELD(battery_beep_volume, F_U8, 0, 0, 100),
    FIELD(web_user, F_STR, 33, 0, 0),
    FIELD(web_password, F_STR, 65, 0, 0),
};

#define FIELD_COUNT (sizeof(FIELDS) / sizeof(FIELDS[0]))

static void *field_ptr_in(const settings_t *s, const field_t *f)
{
    return (uint8_t *)s + f->offset;
}

static void *field_ptr(const field_t *f)
{
    return field_ptr_in(&settings, f);
}

static int32_t field_read_in(const settings_t *s, const field_t *f)
{
    switch (f->type) {
    case F_U8: {
        uint8_t v;
        memcpy(&v, field_ptr_in(s, f), sizeof(v));
        return v;
    }
    case F_U16: {
        uint16_t v;
        memcpy(&v, field_ptr_in(s, f), sizeof(v));
        return v;
    }
    case F_U32: {
        uint32_t v;
        memcpy(&v, field_ptr_in(s, f), sizeof(v));
        return (int32_t)v;
    }
    case F_I8: {
        int8_t v;
        memcpy(&v, field_ptr_in(s, f), sizeof(v));
        return v;
    }
    case F_I16: {
        int16_t v;
        memcpy(&v, field_ptr_in(s, f), sizeof(v));
        return v;
    }
    default: return 0;
    }
}

static void field_write_num(const field_t *f, int32_t v)
{
    switch (f->type) {
    case F_U8: {
        uint8_t x = (uint8_t)v;
        memcpy(field_ptr(f), &x, sizeof(x));
        break;
    }
    case F_U16: {
        uint16_t x = (uint16_t)v;
        memcpy(field_ptr(f), &x, sizeof(x));
        break;
    }
    case F_U32: {
        uint32_t x = (uint32_t)v;
        memcpy(field_ptr(f), &x, sizeof(x));
        break;
    }
    case F_I8: {
        int8_t x = (int8_t)v;
        memcpy(field_ptr(f), &x, sizeof(x));
        break;
    }
    case F_I16: {
        int16_t x = (int16_t)v;
        memcpy(field_ptr(f), &x, sizeof(x));
        break;
    }
    default: break;
    }
}

static bool unreserved(char c)
{
    return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') ||
           (c >= '0' && c <= '9') || c == '-' || c == '_' || c == '.' || c == '~';
}

// Percent encoding of the values the page receives; the client decodes them
// with URLSearchParams.
static void url_encode(const char *in, char *out, size_t cap)
{
    static const char hex[] = "0123456789ABCDEF";
    size_t o = 0;
    for (const unsigned char *p = (const unsigned char *)in; *p && o + 4 < cap; p++) {
        if (unreserved((char)*p)) {
            out[o++] = (char)*p;
        } else {
            out[o++] = '%';
            out[o++] = hex[*p >> 4];
            out[o++] = hex[*p & 0x0F];
        }
    }
    out[o] = '\0';
}

// Inverse of url_encode for the values the page posts ("+" is a space).
static void url_decode(const char *in, char *out, size_t cap)
{
    size_t o = 0;
    for (size_t i = 0; in[i] && o + 1 < cap; i++) {
        if (in[i] == '+') {
            out[o++] = ' ';
        } else if (in[i] == '%' && in[i + 1] && in[i + 2]) {
            char hex[3] = {in[i + 1], in[i + 2], '\0'};
            out[o++] = (char)strtol(hex, NULL, 16);
            i += 2;
        } else {
            out[o++] = in[i];
        }
    }
    out[o] = '\0';
}

//
// Handlers. httpd runs them one at a time in its own task, so the response
// buffers below can be static and stay off the stack.
//

static char resp_buf[6144];

static void touch_activity(void)
{
    last_activity_us = esp_timer_get_time();
}

static esp_err_t index_get(httpd_req_t *req)
{
    if (!auth_ok(req)) return deny(req);
    touch_activity();
    httpd_resp_set_type(req, "text/html");
    return httpd_resp_send(req, index_html, HTTPD_RESP_USE_STRLEN);
}

static esp_err_t config_get(httpd_req_t *req)
{
    if (!auth_ok(req)) return deny(req);
    touch_activity();

    // The labels show what the firmware was built with: the defaults are
    // computed into their own struct, so the live settings stay untouched.
    static settings_t defs;
    settings_defaults_into(&defs);

    size_t pos = 0;
    resp_buf[0] = '\0';
    for (size_t i = 0; i < FIELD_COUNT; i++) {
        const field_t *f = &FIELDS[i];
        char val[192];
        char def[192] = "";
        if (f->type == F_STR) {
            url_encode((const char *)field_ptr(f), val, sizeof(val));
            const char *dflt = (const char *)field_ptr_in(&defs, f);
            if (dflt[0]) url_encode(dflt, def, sizeof(def));
        } else {
            snprintf(val, sizeof(val), "%ld", (long)field_read_in(&settings, f));
            snprintf(def, sizeof(def), "%ld", (long)field_read_in(&defs, f));
        }

        int n = snprintf(resp_buf + pos, sizeof(resp_buf) - pos, "%s%s=%s",
                         i ? "&" : "", f->key, val);
        if (n < 0 || (size_t)n >= sizeof(resp_buf) - pos) break;
        pos += (size_t)n;

        if (def[0] != '\0') {
            n = snprintf(resp_buf + pos, sizeof(resp_buf) - pos, "&%s.def=%s",
                         f->key, def);
            if (n < 0 || (size_t)n >= sizeof(resp_buf) - pos) break;
            pos += (size_t)n;
        }
    }

    httpd_resp_set_type(req, "application/x-www-form-urlencoded");
    return httpd_resp_send(req, resp_buf, HTTPD_RESP_USE_STRLEN);
}

static esp_err_t config_post(httpd_req_t *req)
{
    if (!auth_ok(req)) return deny(req);
    touch_activity();

    static char body[1024];
    size_t total = 0;
    while (total < sizeof(body) - 1) {
        int n = httpd_req_recv(req, body + total, sizeof(body) - 1 - total);
        if (n <= 0) break;
        total += (size_t)n;
    }
    body[total] = '\0';

    int applied = 0;
    for (char *kv = strtok(body, "&"); kv != NULL; kv = strtok(NULL, "&")) {
        char *eq = strchr(kv, '=');
        if (eq == NULL) continue;
        *eq = '\0';

        char key[40];
        char val[160];
        url_decode(kv, key, sizeof(key));
        url_decode(eq + 1, val, sizeof(val));

        const field_t *f = NULL;
        for (size_t i = 0; i < FIELD_COUNT; i++) {
            if (strcmp(FIELDS[i].key, key) == 0) {
                f = &FIELDS[i];
                break;
            }
        }
        if (f == NULL) continue;

        if (f->type == F_STR) {
            snprintf((char *)field_ptr(f), f->size, "%s", val);
        } else {
            int32_t v = (int32_t)strtol(val, NULL, 10);
            if (v < f->lo) v = f->lo;
            if (v > f->hi) v = f->hi;
            field_write_num(f, v);
        }
        applied++;
    }

    settings_save();
    clock_apply_timezone(); // the zone is applied on every render

    char msg[48];
    snprintf(msg, sizeof(msg), "ok, %d values stored", applied);
    httpd_resp_set_type(req, "text/plain");
    return httpd_resp_send(req, msg, HTTPD_RESP_USE_STRLEN);
}

static esp_err_t reset_post(httpd_req_t *req)
{
    if (!auth_ok(req)) return deny(req);
    touch_activity();
    if (settings_reset_defaults() != ESP_OK) {
        return httpd_resp_send_err(req, HTTPD_500_INTERNAL_SERVER_ERROR,
                                   "reset failed");
    }
    clock_apply_timezone(); // the zone is applied on every render
    httpd_resp_set_type(req, "text/plain");
    return httpd_resp_send(req, "reset done", HTTPD_RESP_USE_STRLEN);
}

static esp_err_t shutdown_post(httpd_req_t *req)
{
    if (!auth_ok(req)) return deny(req);
    touch_activity();
    httpd_resp_send(req, "stopping", HTTPD_RESP_USE_STRLEN);
    spawn(false); // after the response has gone out
    return ESP_OK;
}

static const httpd_uri_t URI_INDEX = {
    .uri = "/", .method = HTTP_GET, .handler = index_get,
};
static const httpd_uri_t URI_CONFIG_GET = {
    .uri = "/api/config", .method = HTTP_GET, .handler = config_get,
};
static const httpd_uri_t URI_CONFIG_POST = {
    .uri = "/api/config", .method = HTTP_POST, .handler = config_post,
};
static const httpd_uri_t URI_SHUTDOWN = {
    .uri = "/api/shutdown", .method = HTTP_POST, .handler = shutdown_post,
};
static const httpd_uri_t URI_RESET = {
    .uri = "/api/reset", .method = HTTP_POST, .handler = reset_post,
};

//
// Start and stop. Both run in their own task: the connect and the TLS
// handshake block for seconds.
//

static esp_timer_handle_t idle_timer = NULL;

static void idle_timer_cb(void *arg);

static void start_idle_timer(void)
{
    if (idle_timer) return;
    const esp_timer_create_args_t args = {
        .callback = idle_timer_cb,
        .name = "web_idle",
    };
    if (esp_timer_create(&args, &idle_timer) != ESP_OK) {
        ESP_LOGW(TAG, "idle timer unavailable, the server stays up");
        return;
    }
    esp_timer_start_periodic(idle_timer, 30 * 1000000LL);
}

static void stop_idle_timer(void)
{
    if (!idle_timer) return;
    esp_timer_stop(idle_timer);
    esp_timer_delete(idle_timer);
    idle_timer = NULL;
}

// The page closes itself after the configured time without requests, so a
// forgotten session does not keep the radio up all night.
static void idle_timer_cb(void *arg)
{
    int64_t idle_s = (esp_timer_get_time() - last_activity_us) / 1000000LL;
    int64_t limit = (int64_t)settings.web_idle_timeout_min * 60;
    if (idle_s >= limit) {
        ESP_LOGI(TAG, "no request for %lld min, shutting down", (long long)limit / 60);
        spawn(false);
    }
}

static bool start_server(void)
{
    if (server) return true;

    if (!net_wifi_up()) {
        ESP_LOGE(TAG, "no WiFi, the setup page cannot be reached");
        return false;
    }

    esp_netif_t *netif = esp_netif_get_handle_from_ifkey("WIFI_STA_DEF");
    esp_netif_ip_info_t ip = {0};
    if (!netif || esp_netif_get_ip_info(netif, &ip) != ESP_OK || ip.ip.addr == 0) {
        ESP_LOGE(TAG, "no address after the WiFi connect");
        net_wifi_down();
        return false;
    }

    // Hold the link: the daily NTP sync may bring the radio down again, and
    // the page must survive that.
    net_wifi_hold();
    build_expected_auth();

    httpd_ssl_config_t conf = HTTPD_SSL_CONFIG_DEFAULT();
    conf.httpd.max_open_sockets = WEB_SOCKETS;
    // A browser sends 700-900 bytes of request headers, the 512 byte default
    // of the httpd makes it answer "Header fields are too long".
    conf.httpd.max_req_hdr_len = 2048;
    // mbedtls wants PEM buffers with their terminating NUL counted in the
    // length; without it, the parse fails with a buffer error.
    conf.servercert = (const uint8_t *)server_cert_pem;
    conf.servercert_len = sizeof(server_cert_pem);
    conf.prvtkey_pem = (const uint8_t *)server_key_pem;
    conf.prvtkey_len = sizeof(server_key_pem);
    conf.transport_mode = HTTPD_SSL_TRANSPORT_SECURE;

    esp_err_t err = httpd_ssl_start(&server, &conf);
    if (err != ESP_OK) {
        // Most likely not enough heap left for a second TLS socket; one
        // connection still serves the page, the browser reuses it.
        ESP_LOGW(TAG, "https start failed (%s), retrying with one socket",
                 esp_err_to_name(err));
        conf.httpd.max_open_sockets = 1;
        err = httpd_ssl_start(&server, &conf);
    }
    if (err != ESP_OK) {
        ESP_LOGE(TAG, "https server not started: %s", esp_err_to_name(err));
        server = NULL;
        net_wifi_release();
        net_wifi_down();
        return false;
    }

    httpd_register_uri_handler(server, &URI_INDEX);
    httpd_register_uri_handler(server, &URI_CONFIG_GET);
    httpd_register_uri_handler(server, &URI_CONFIG_POST);
    httpd_register_uri_handler(server, &URI_SHUTDOWN);
    httpd_register_uri_handler(server, &URI_RESET);

    snprintf(ui_status.ip, sizeof(ui_status.ip), IPSTR, IP2STR(&ip.ip));
    ui_status.web_server = true;
    last_activity_us = esp_timer_get_time();
    start_idle_timer();

    ESP_LOGI(TAG, "setup page: https://%s/", ui_status.ip);
    if (expected_auth[0] != '\0') {
        ESP_LOGI(TAG, "login: %s", settings.web_user);
    } else {
        ESP_LOGW(TAG, "no login set, the page is open in the local network");
    }
    ESP_LOGI(TAG, "free heap %u bytes", (unsigned)esp_get_free_heap_size());
    ui_force_redraw();
    return true;
}

static void stop_server(void)
{
    stop_idle_timer();

    if (server) {
        httpd_handle_t handle = server;
        server = NULL;
        httpd_ssl_stop(handle);
        ESP_LOGI(TAG, "setup page closed");
    }

    ui_status.web_server = false;
    ui_status.ip[0] = '\0';
    ui_force_redraw();

    net_wifi_release();
    net_wifi_down();
}

static void web_task(void *arg)
{
    bool start = (bool)(intptr_t)arg;
    if (start) {
        start_server();
    } else {
        stop_server();
    }
    busy = false;
    vTaskDelete(NULL);
}

static void spawn(bool start)
{
    if (busy) return; // a toggle while the server is still starting
    busy = true;
    if (xTaskCreate(web_task, "web_setup", 6144, (void *)(intptr_t)start, 5, NULL)
        != pdPASS) {
        busy = false;
        ESP_LOGE(TAG, "setup task not created");
    }
}

void web_start(void)
{
    if (!server) spawn(true);
}

void web_stop(void)
{
    if (server) spawn(false);
}

void web_toggle(void)
{
    spawn(!server);
}

bool web_is_running(void)
{
    return server != NULL;
}
